  assert.strictEqual(markPaid(invoice).status, "paid");
});

test("refuses to pay a draft", () => {
  const invoice = { id: "R-7", customer: "Acme", cents: 990, status: "draft" };
  assert.throws(() => markPaid(invoice), /cannot pay an invoice that is draft/);
});

